// Solo reestructura datos (agrega TODOS los items del listado real en un
// unico array) -- NUNCA decide REGLA G aqui (eso lo hace v3.ingesta en
// Python). Nunca usa $input.first()/"primer resultado" para elegir un
// archivo: se reenvia el listado COMPLETO tal cual llego de Drive.
const params = $('RUTEAR - source_mode (IF)').first().json;
const items = $input.all().map((item) => item.json);

return [{
  json: {
    fecha_inicio: params.fecha_inicio,
    fecha_fin: params.fecha_fin,
    source_mode: params.source_mode,
    candidatos_drive_crudo: items,
  },
}];

// Modo fixture: candidatos_por_fecha ya viene armado desde el trigger,
// sin tocar Drive. Ningun cambio de comportamiento respecto a FASE 5-9.
const params = $('RUTEAR - source_mode (IF)').first().json;

return [{
  json: {
    fecha_inicio: params.fecha_inicio,
    fecha_fin: params.fecha_fin,
    source_mode: params.source_mode || 'fixture',
    candidatos_por_fecha: params.candidatos_por_fecha || {},
  },
}];

// Arma el payload para v3.ingesta (Python, unica autoridad -- ver
// v3/TECHNICAL_DEBT.md DEBT-001, cerrado en FASE 10A). Este nodo NUNCA
// decide REGLA G: solo reenvia lo que ya vino armado de la rama fixture o
// drive_readonly.
const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

const payload = {
  fecha_inicio: t.fecha_inicio,
  fecha_fin: t.fecha_fin,
  source_mode: t.source_mode,
};
if (t.source_mode === 'drive_readonly') {
  payload.candidatos_drive_crudo = t.candidatos_drive_crudo || [];
} else {
  payload.candidatos_por_fecha = t.candidatos_por_fecha || {};
}

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_ingesta_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_ingesta_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

// SOLO para pruebas manuales reales de este subworkflow de forma aislada
// (FASE 10A) -- el pipeline real (llamado desde el workflow principal)
// SIEMPRE usa "ENTRADA (Execute Workflow Trigger)". Ajustar aqui el rango
// y el source_mode antes de ejecutar manualmente desde n8n.
return [{
  json: {
    fecha_inicio: '2026-09-01',
    fecha_fin: '2026-09-30',
    source_mode: 'drive_readonly',
    drive_folder_entrada: '1ntneoE3MI-25FyPXUymXEvIJmnaZWyJ1',
    candidatos_por_fecha: {},
  },
}];
